package cc.ataglace.molebutter.app.internal;
import org.springframework.web.bind.annotation.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import cc.ataglace.molebutter.identity.api.UserPrincipal;import cc.ataglace.molebutter.marketplace.api.*;
@RestController @RequestMapping("/api/marketplaces/lotteon") final class LotteonProductController {
 private final LotteonProducts products;LotteonProductController(LotteonProducts products){this.products=products;}
 @GetMapping("/products") ApiResponse<PartnerEditor.ProductPage> list(@AuthenticationPrincipal UserPrincipal actor,@RequestParam(required=false)String productId,@RequestParam(required=false)String name,@RequestParam(required=false)String status,@RequestParam(required=false)String from,@RequestParam(required=false)String to,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.success(products.list(actor.userId(),new LotteonProducts.Query(productId,name,status,from,to,page,size)));}
 @GetMapping("/products/{productId}") ApiResponse<LotteonProducts.Detail> get(@AuthenticationPrincipal UserPrincipal actor,@PathVariable String productId){return ApiResponse.success(products.get(actor.userId(),productId));}
 @GetMapping("/schema") ApiResponse<PartnerEditor.Schema> schema(@AuthenticationPrincipal UserPrincipal actor){return ApiResponse.success(products.schema(actor.userId()));}
 @GetMapping("/metadata/{kind}") ApiResponse<java.util.List<LotteonProducts.Choice>> metadata(@AuthenticationPrincipal UserPrincipal actor,@PathVariable String kind,@RequestParam(required=false)String filter,@RequestParam(defaultValue="0")int page){return ApiResponse.success(products.metadata(actor.userId(),kind,filter,page));}
 @GetMapping("/metadata/{kind}/page") ApiResponse<LotteonProducts.ChoicePage> metadataPage(@AuthenticationPrincipal UserPrincipal actor,@PathVariable String kind,@RequestParam(required=false)String filter,@RequestParam(required=false)String parent,@RequestParam(defaultValue="0")int page){return ApiResponse.success(products.metadataPage(actor.userId(),kind,filter,parent,page));}
 @ExceptionHandler(cc.ataglace.molebutter.common.api.InputValidationFailure.class) org.springframework.http.ResponseEntity<ApiResponse<Void>> invalid(cc.ataglace.molebutter.common.api.InputValidationFailure f){return org.springframework.http.ResponseEntity.badRequest().body(ApiResponse.error(org.springframework.http.HttpStatus.BAD_REQUEST,"INVALID_INPUT",f.getMessage()));}
 @ExceptionHandler(MarketplaceFailure.class) org.springframework.http.ResponseEntity<ApiResponse<Void>> external(MarketplaceFailure f){var status=switch(f.kind()){case CONFIGURATION->org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE;case RATE_LIMIT->org.springframework.http.HttpStatus.TOO_MANY_REQUESTS;case TIMEOUT->org.springframework.http.HttpStatus.GATEWAY_TIMEOUT;default->org.springframework.http.HttpStatus.BAD_GATEWAY;};return org.springframework.http.ResponseEntity.status(status).body(ApiResponse.error(status,"LOTTEON_"+f.kind(),f.getMessage()));}
}
